"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["78017"],{69487(e){e.exports=JSON.parse('{"id":"FIN-776","slug":"consumer-confidence","term":"Consumer Confidence","also_known_as":[],"difficulty":"Intermediate","definition":"Consumer confidence is a measure of how optimistic or pessimistic households feel about the economy and their own financial situation, usually based on regular surveys.","explanation":["Consumer confidence surveys ask people questions such as whether they think their finances will improve, whether now is a good time to make major purchases, and how they expect the economy and job market to perform.","Consumer spending makes up a large share of economic activity in many countries, so household mood matters. When people feel confident, they tend to spend more and borrow more, supporting economic growth. When they feel worried, they tend to save more and delay major purchases, such as cars, holidays and home improvements.","For example, a sharp drop in consumer confidence following news of job losses or rising prices might signal that retail sales and economic growth will weaken in the coming months.","Consumer confidence is often treated as a leading indicator. However, the link between what people say in surveys and what they actually do is not always strong. Confidence can be affected by news headlines, political events and stock market swings, while actual spending depends more directly on incomes, employment and access to credit."],"note":"","total":1500,"prev":{"slug":"consolidation","term":"Consolidation"},"next":{"slug":"consumer-price-index","term":"Consumer Price Index (CPI)"}}')}}]);